    dict(slug="preop", name="PreOp", category="Clinical practice", title="Perioperative references in a practical workflow", summary="Risk calculators, medication references and planning tools for work before surgery.", audience="Healthcare professionals preparing and reviewing perioperative assessments.", why="Preoperative planning involves several decisions and sources. PreOp brings commonly used tools into a focused interface so clinicians can review them in context.", details=[("Risk assessment", "Use calculators as aids to structured assessment."), ("Medication references", "Review relevant perioperative medication considerations."), ("Planning support", "Bring assessment and handoff information together.")], steps=[("Open the relevant tool", "Choose the assessment or reference that fits the question."), ("Check the inputs", "Verify patient facts and local policy outside the tool."), ("Apply judgment", "Interpret outputs in the clinical setting with the responsible team.")], note="PreOp is a reference aid, not a substitute for current guidelines, local protocols or clinician judgment.", url="https://www.bayan.edu.om/preop", cta="Explore PreOp", image="/assets/screens/preop-01-assessment-desktop.png", logo="/assets/logos/preop-mark-white.png", image_label="Illustrative PreOp assessment interface"),
    dict(slug="journalready", name="JournalReady", category="Research", title="A clearer route from research idea to manuscript", summary="Practical tools for study planning, analysis, references and manuscript preparation.", audience="Researchers and clinicians working on study design, writing and publication.", why="Research work can become fragmented across notes, calculations and submission requirements. JournalReady brings those tasks into a connected workflow.", details=[("Plan the study", "Frame a research question and consider methods and feasibility."), ("Work with evidence", "Organize references and interpret analysis outputs with care."), ("Prepare the manuscript", "Structure writing and consider suitable journals and submission requirements.")], steps=[("Start with the question", "Describe the objective and study context."), ("Build the work", "Use the relevant planning, analysis and writing tools."), ("Review before submission", "Check sources, methods, authorship and journal requirements yourself.")], note="AI assistance does not establish the validity of a study, analysis or citation. Researchers remain responsible for verification.", url="https://journalready.ai/", cta="Explore JournalReady", image="/assets/screens/journalready-01-study-desktop.png", logo="/assets/logos/journalready-mark-white.png", image_label="Illustrative JournalReady study planning interface"),
