    dict(slug="ohealth", name="OHealth", category="Intelligence", title="Oman's open health data, easier to explore", summary="Explore health indicators, capacity and trends using open data from Oman.", audience="Researchers, planners and others exploring questions about health systems in Oman.", why="Public data is useful when people can inspect it and understand its limits. OHealth turns selected open datasets into interactive views for exploration.", details=[("Explore indicators", "See available health-system measures in context."), ("Compare places and time", "Inspect geographic patterns and changes over time where data allows."), ("Trace the source", "Use source information before drawing conclusions from a visualisation.")], steps=[("Choose a question", "Select a health-system topic or area."), ("Explore the view", "Compare values and inspect the available context."), ("Check interpretation", "Review the source, definitions and data limitations.")], note="Visualisations support exploration and do not establish causes or predict individual outcomes.", url="https://ohealth.medresearch-academy.om/", cta="Explore OHealth", image="/assets/screens/ohealth-01-indicators-desktop.png", logo="/assets/logos/ohealth-mark-white.png", image_label="Illustrative OHealth indicator interface"),
