def e(value):
    return escape(str(value), quote=True)

def header():
    return '<a class="skip" href="#main">Skip to content</a><header class="solution-header"><a class="solution-brand" href="/"><img src="/assets/logos/bayan-ai-mark-white.png" alt=""><span>Bayan AI<small>SCIENCE &amp; INNOVATION</small></span></a><nav class="solution-nav" aria-label="Main navigation"><a href="/solutions">Solutions</a><a href="/#research">Research</a><a href="/#contact">Contact</a></nav></header>'

def footer():
    return '<footer class="site-footer"><span>© 2026 Bayan AI Technologies LLC · Muscat, Oman</span><nav aria-label="Footer navigation"><a href="/">Home</a><a href="/solutions">All solutions</a><a href="mailto:info@bayanai.tech">Contact</a></nav></footer>'

def page_shell(title, description, path, content, image):
    canonical = BASE + path
    structured = {"@context":"https://schema.org","@type":"WebPage","name":title,"description":description,"url":canonical,"isPartOf":{"@type":"WebSite","name":"Bayan AI Technologies","url":BASE}}
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)}</title><meta name="description" content="{e(description)}"><link rel="canonical" href="{e(canonical)}"><meta name="theme-color" content="#0b1a28"><meta property="og:type" content="website"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(description)}"><meta property="og:url" content="{e(canonical)}"><meta property="og:image" content="{e(BASE + image)}"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/assets/logos/bayan-ai-mark-white.png"><link rel="stylesheet" href="/solutions.css"><script type="application/ld+json">{json.dumps(structured, ensure_ascii=False)}</script></head><body>{header()}<main id="main">{content}</main>{footer()}</body></html>'''

def card(product):
    return f'<a class="solution-card" href="/solutions/{e(product["slug"])}"><img src="{e(product["logo"])}" alt="" loading="lazy"><span><small>{e(product["category"])}</small><h3>{e(product["name"])}</h3><p>{e(product["summary"])}</p><span class="explore">Explore solution ↗</span></span></a>'

def index_page():
    intro = '<section class="hero"><div class="hero-inner"><p class="eyebrow">Bayan AI Technologies · From Oman</p><h1>Different questions.<br><em>Shared purpose.</em></h1><p class="lead">Explore our work in medical education, clinical practice, research and open data. Each solution has its own scope, audience and next step.</p><div class="trail"><a href="/">Company home</a><span>Eight initiatives</span></div></div></section>'
    grid = ''.join(card(p) for p in PRODUCTS)
    body = intro + f'<section class="section"><div class="wrap"><div class="section-intro"><div><p class="eyebrow">Our solutions</p><h2>Find the work behind<br><em>the name.</em></h2></div><p>Some are public applications. Others are research or institution-led tools. Open each page to see what it does and where it stands.</p></div><div class="solution-grid">{grid}</div></div></section>'
    body += '<section class="section soft"><div class="wrap"><div class="cta"><div><p class="eyebrow">Research & collaboration</p><h2>A question worth<br><em>working on together?</em></h2><p>We welcome conversations with healthcare, education and research teams about evaluation and practical use.</p></div><a class="button" href="mailto:info@bayanai.tech?subject=Bayan%20AI%20collaboration">Contact the team</a></div></div></section>'
    return page_shell('Solutions | Bayan AI Technologies', 'Explore Bayan AI solutions in medical education, nursing English, perioperative practice, research, Arabic clinical language and open data.', '/solutions', body, '/artwork/ai-oman.jpg')

def product_page(p):
    slug = p['slug']
    hero = f'<section class="hero"><div class="hero-inner hero-grid"><div><p class="eyebrow">{e(p["category"])} · Bayan AI Technologies</p><h1>{e(p["title"])}</h1><p class="lead">{e(p["summary"])}</p><div class="trail"><a href="/solutions">All solutions</a><span>{e(p["name"])}</span></div></div><figure class="hero-visual {"phone" if p.get("phone") else ""}"><img src="{e(p["image"])}" alt="{e(p["image_label"])}"><figcaption>{"Actual app screen" if p.get("phone") else "Illustrative interface based on the project’s described features"}</figcaption></figure></div></section>'
    details = ''.join(f'<li><b>{i:02d}</b><div><strong>{e(title)}</strong><span>{e(text)}</span></div></li>' for i,(title,text) in enumerate(p['details'],1))
    body = hero + f'<section class="section"><div class="wrap split"><div><p class="eyebrow">The purpose</p><h2>Built around<br><em>a real question.</em></h2><p class="intro-copy">{e(p["why"])}</p><p><strong>For:</strong> {e(p["audience"])}</p></div><ol class="detail-list">{details}</ol></div></section>'
    steps = ''.join(f'<article><span>{i:02d} / 03</span><h3>{e(title)}</h3><p>{e(text)}</p></article>' for i,(title,text) in enumerate(p['steps'],1))
    body += f'<section class="section soft"><div class="wrap"><p class="eyebrow">How to engage</p><h2>From interest<br><em>to use.</em></h2><div class="workflow">{steps}</div><p class="note">{e(p["note"])}</p></div></section>'
    buttons = f'<a class="button" href="{e(p["url"])}" target="_blank" rel="noopener">{e(p["cta"])} ↗</a>'
    for label,url in p.get('extra', []):
        buttons += f'<a class="button outline" href="{e(url)}" target="_blank" rel="noopener">{e(label)} ↗</a>'
    body += f'<section class="section"><div class="wrap"><div class="cta"><div><p class="eyebrow">Next step</p><h2>Explore {e(p["name"])}.</h2><p>Visit the project to see its current experience and availability.</p><div class="buttons">{buttons}</div></div><a class="text-link" href="/solutions">See all solutions ↗</a></div></div></section>'
    related = [item for item in PRODUCTS if item['slug'] != slug][:3]
    body += '<section class="section soft"><div class="wrap"><p class="eyebrow">Across the company</p><h2>Keep exploring.</h2><div class="related">' + ''.join(f'<a href="/solutions/{e(item["slug"])}"><small>{e(item["category"])}</small><strong>{e(item["name"])} ↗</strong></a>' for item in related) + '</div></div></section>'
    return page_shell(f'{p["name"]} | Bayan AI Technologies', p['summary'] + ' ' + p['audience'], f'/solutions/{slug}', body, p['image'])

def main():
    folder = ROOT / 'solutions'
    folder.mkdir(exist_ok=True)
    (folder / 'index.html').write_text(index_page(), encoding='utf-8')
    for p in PRODUCTS:
        page = folder / p['slug']
        page.mkdir(exist_ok=True)
        (page / 'index.html').write_text(product_page(p), encoding='utf-8')
    print(f'Generated {len(PRODUCTS) + 1} solution pages')

if __name__ == '__main__':
    main()
